type SendState = 'sending' | 'retrying' | 'failed' | 'confirmed';

interface Message {
  conversationId: string;
  clientMessageId: string;
  messageId: string | null;
  sequence: number | null;
  senderId: string;
  body: string;
  sentAt: string | null;
  sendState: SendState;
}

interface ConversationSummary {
  conversationId: string;
  title: string;
  participantIds: string[];
  lastSequence: number;
  unreadCount: number;
  preview: string;
  updatedAt: string;
}

interface ThreadState {
  conversationId: string;
  confirmed: Message[];
  pending: Message[];
  oldestSequence: number | null;
  hasOlder: boolean;
  readMarkerSequence: number;
}

interface TypingSignal {
  conversationId: string;
  userId: string;
  expiresAt: string;
}

type ConnectionState = 'connecting' | 'live' | 'catching-up' | 'offline' | 'resyncing';

interface InboxState {
  conversations: Record<string, ConversationSummary>;
  orderedIds: string[];
  threads: Record<string, ThreadState>;
  typing: TypingSignal[];
  inboxCursor: number;
  connection: ConnectionState;
}
